#[derive(Debug)]
pub struct ContextSourceClient {
    read_resource: NativeRequestHandle<ContextSourceReadResource>,
    render_prompt: NativeRequestHandle<ContextSourceRenderPrompt>,
    snapshot: NativeRequestHandle<ContextSourceSnapshot>,
}
impl ContextSourceClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_requirement(dependencies, requirement_id)
    }

    pub async fn read_resource(&self, request: ReadResourceRequest) -> Result<ReadResourceResponse, ContextSourceReadResourceInvocationError> {
        self.read_resource.invoke(READ_RESOURCE_OPERATION, request).await
            .map_err(ContextSourceReadResourceInvocationError::Runtime)?
            .map_err(ContextSourceReadResourceInvocationError::Domain)
    }

    pub async fn read_resource_with_context(&self, context: InvocationContext, request: ReadResourceRequest) -> Result<ReadResourceResponse, ContextSourceReadResourceInvocationError> {
        self.read_resource.invoke_with_context(READ_RESOURCE_OPERATION, context, request).await
            .map_err(ContextSourceReadResourceInvocationError::Runtime)?
            .map_err(ContextSourceReadResourceInvocationError::Domain)
    }

    pub async fn render_prompt(&self, request: RenderPromptRequest) -> Result<RenderPromptResponse, ContextSourceRenderPromptInvocationError> {
        self.render_prompt.invoke(RENDER_PROMPT_OPERATION, request).await
            .map_err(ContextSourceRenderPromptInvocationError::Runtime)?
            .map_err(ContextSourceRenderPromptInvocationError::Domain)
    }

    pub async fn render_prompt_with_context(&self, context: InvocationContext, request: RenderPromptRequest) -> Result<RenderPromptResponse, ContextSourceRenderPromptInvocationError> {
        self.render_prompt.invoke_with_context(RENDER_PROMPT_OPERATION, context, request).await
            .map_err(ContextSourceRenderPromptInvocationError::Runtime)?
            .map_err(ContextSourceRenderPromptInvocationError::Domain)
    }

    pub async fn snapshot(&self, request: SnapshotRequest) -> Result<SnapshotResponse, ContextSourceSnapshotInvocationError> {
        self.snapshot.invoke(SNAPSHOT_OPERATION, request).await
            .map_err(ContextSourceSnapshotInvocationError::Runtime)?
            .map_err(ContextSourceSnapshotInvocationError::Domain)
    }

    pub async fn snapshot_with_context(&self, context: InvocationContext, request: SnapshotRequest) -> Result<SnapshotResponse, ContextSourceSnapshotInvocationError> {
        self.snapshot.invoke_with_context(SNAPSHOT_OPERATION, context, request).await
            .map_err(ContextSourceSnapshotInvocationError::Runtime)?
            .map_err(ContextSourceSnapshotInvocationError::Domain)
    }
}

impl CapabilityClient for ContextSourceClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            read_resource: dependencies.one::<ContextSourceReadResource>()?,
            render_prompt: dependencies.one::<ContextSourceRenderPrompt>()?,
            snapshot: dependencies.one::<ContextSourceSnapshot>()?,
        })
    }

    fn from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Self, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::from_dependencies(&dependencies)
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for ContextSourceClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    read_resource: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ContextSourceReadResource>()?,
                    render_prompt: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ContextSourceRenderPrompt>()?,
                    snapshot: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<ContextSourceSnapshot>()?,
                    },
                ))
            })
            .collect()
    }

    fn many_from_requirement(
        dependencies: &PluginDependencies,
        requirement_id: &str,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        let dependencies = dependencies.requirement(requirement_id)?;
        Self::many_from_dependencies(&dependencies)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum ContextSourceReadResourceInvocationError {
    Domain(ReadResourceError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum ContextSourceRenderPromptInvocationError {
    Domain(RenderPromptError),
    Runtime(RuntimeFailure),
}
#[derive(Clone, Debug, PartialEq)]
pub enum ContextSourceSnapshotInvocationError {
    Domain(SnapshotError),
    Runtime(RuntimeFailure),
}

#[derive(Clone, Copy, Debug)]
pub struct ContextSourceGuestClient<'a, H: lenso_guest_sdk::HostImports> {
    capability: lenso_guest_sdk::GuestCapability<'a, H>,
}

impl<'a, H: lenso_guest_sdk::HostImports> ContextSourceGuestClient<'a, H> {
    pub fn from_context(context: &'a lenso_guest_sdk::GuestContext<H>) -> Result<Self, lenso_guest_sdk::GuestError<serde_json::Value>> {
        context
            .require(CAPABILITY_ID, DESCRIPTOR_VERSION, &[READ_RESOURCE_OPERATION, RENDER_PROMPT_OPERATION, SNAPSHOT_OPERATION], &[])
            .map(|capability| Self { capability })
    }

    pub fn read_resource(&self, request: &ReadResourceRequest) -> Result<ReadResourceResponse, lenso_guest_sdk::GuestError<ReadResourceError>> {
        self.capability.request(READ_RESOURCE_OPERATION, request)
    }

    pub fn render_prompt(&self, request: &RenderPromptRequest) -> Result<RenderPromptResponse, lenso_guest_sdk::GuestError<RenderPromptError>> {
        self.capability.request(RENDER_PROMPT_OPERATION, request)
    }

    pub fn snapshot(&self, request: &SnapshotRequest) -> Result<SnapshotResponse, lenso_guest_sdk::GuestError<SnapshotError>> {
        self.capability.request(SNAPSHOT_OPERATION, request)
    }
}

#[derive(Debug, Default)]
pub struct ContextSourceJsonCodec;

impl lenso_runtime_codec::JsonCapabilityCodec for ContextSourceJsonCodec {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }

    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }

    fn descriptor_digest(&self) -> &'static str { DESCRIPTOR_DIGEST }

    fn request_operations(&self) -> &'static [&'static str] { &[READ_RESOURCE_OPERATION, RENDER_PROMPT_OPERATION, SNAPSHOT_OPERATION] }
    fn stream_operations(&self) -> &'static [&'static str] { &[] }

    fn encode_request(&self, operation: &str, request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        match operation {
            READ_RESOURCE_OPERATION => {
                let value = request.downcast_ref::<ReadResourceRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            RENDER_PROMPT_OPERATION => {
                let value = request.downcast_ref::<RenderPromptRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            SNAPSHOT_OPERATION => {
                let value = request.downcast_ref::<SnapshotRequest>().ok_or_else(runtime_codec_protocol_failure)?;
                serde_json::to_value(value).map_err(|_| runtime_codec_protocol_failure())
            },
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_response(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            READ_RESOURCE_OPERATION => serde_json::from_value::<ReadResourceResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            RENDER_PROMPT_OPERATION => serde_json::from_value::<RenderPromptResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SNAPSHOT_OPERATION => serde_json::from_value::<SnapshotResponse>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn decode_domain_error(&self, operation: &str, value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        match operation {
            READ_RESOURCE_OPERATION => serde_json::from_value::<ReadResourceError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            RENDER_PROMPT_OPERATION => serde_json::from_value::<RenderPromptError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            SNAPSHOT_OPERATION => serde_json::from_value::<SnapshotError>(value)
                .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                .map_err(|_| runtime_codec_protocol_failure()),
            _ => Err(runtime_codec_unknown_operation(operation)),
        }
    }

    fn encode_stream_open(&self, operation: &str, _request: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn encode_stream_message(&self, operation: &str, _message: &dyn std::any::Any) -> Result<serde_json::Value, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_message(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn decode_stream_domain_error(&self, operation: &str, _value: serde_json::Value) -> Result<Box<dyn std::any::Any>, RuntimeFailure> {
        Err(runtime_codec_unknown_operation(operation))
    }

    fn invoke_host_request(&self, dependency: lenso_kernel::PluginDependencyHandle, operation: String, request: serde_json::Value, context: InvocationContext) -> lenso_runtime_codec::JsonHostRequestFuture {
        match operation.as_str() {
            READ_RESOURCE_OPERATION => {
                let request = serde_json::from_value::<ReadResourceRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ContextSourceReadResource>()?;
                    match handle.invoke_with_context(READ_RESOURCE_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            RENDER_PROMPT_OPERATION => {
                let request = serde_json::from_value::<RenderPromptRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ContextSourceRenderPrompt>()?;
                    match handle.invoke_with_context(RENDER_PROMPT_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            SNAPSHOT_OPERATION => {
                let request = serde_json::from_value::<SnapshotRequest>(request).map_err(|_| runtime_codec_protocol_failure());
                Box::pin(async move {
                    let request = request?;
                    let handle = dependency.typed::<ContextSourceSnapshot>()?;
                    match handle.invoke_with_context(SNAPSHOT_OPERATION, context, request).await? {
                        Ok(response) => serde_json::to_value(response)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::Success)
                            .map_err(|_| runtime_codec_protocol_failure()),
                        Err(error) => serde_json::to_value(error)
                            .map(lenso_runtime_codec::JsonInvocationOutcome::DomainError)
                            .map_err(|_| runtime_codec_protocol_failure()),
                    }
                })
            },
            _ => Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation)))),
        }
    }

    fn open_host_stream(&self, _dependency: lenso_kernel::PluginStreamDependencyHandle, operation: String, _request: serde_json::Value, _context: InvocationContext) -> lenso_runtime_codec::JsonHostStreamOpenFuture {
        Box::pin(std::future::ready(Err(runtime_codec_unknown_operation(&operation))))
    }
}

fn runtime_codec_protocol_failure() -> RuntimeFailure { RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID } }

fn runtime_codec_unknown_operation(operation: &str) -> RuntimeFailure {
    RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }
}
